c.STDIO:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[10002];
    fgets(line, sizeof(line), stdin);
    int count = 0, inside_word = 0;
    for (int i = 0; line[i] != '\0'; ++i) {
        char letter = line[i];
        int is_letter = (letter >= 'a' && letter <= 'z') || (letter >= 'A' && letter <= 'Z');
        if (is_letter && !inside_word) {
            ++count;
        }
        inside_word = is_letter;
    }
    printf("%d\n", count);
    return 0;
}

